script:
if doc.custom_mode_of_paiement:

    credit_to = frappe.db.get_value(
        "Mode of Payment Account",
        filters={
            "company": doc.company,
            "parent": doc.custom_mode_of_paiement
        },
        fieldname="custom_credit_to"
    )
    if credit_to:
        doc.credit_to = credit_to

if doc.pending_purchase_invoice:
    due_date = frappe.db.get_value('Pending Purchase Invoice', doc.pending_purchase_invoice, "due_date")
    if due_date:
        doc.due_date = due_date

doc.save()

if doc.custom_mode_of_paiement:

    credit_to = frappe.db.get_value(
        "Mode of Payment Account",
        filters={
            "company": doc.company,
            "parent": doc.custom_mode_of_paiement
        },
        fieldname="custom_credit_to"
    )
    if credit_to:
        doc.credit_to = credit_to

# Puisque on arrive pas à récuppérer la date d'échéance on fait ce truc bizarre
# On l'écrase si elle est égale à la bill_date (ça veut dire qu'on beu)
if doc.bill_date == doc.due_date and doc.pending_purchase_invoice:
    due_date = frappe.db.get_value('Pending Purchase Invoice', doc.pending_purchase_invoice, "due_date")
    if due_date:
        doc.due_date = due_date

if doc.status == "Paid":
    doc.custom_disputed = 0
    doc.custom_déposé_sur_chorus = 0

sales_order = frappe.get_doc("Sales Order", doc.parent)


items_status = [el.custom_statut_interne for el in sales_order.items]
total_ordered = sum([ 1 if el != "" else 0 for el in items_status])
if total_ordered > 0:
    total_received = sum([ 1 if el == "🟢" else 0 for el in items_status])
    total_started = sum([ 1 if el == "🟠" or el == "⚫️" else 0 for el in items_status])
    if total_received == 0 and total_started > 0:
        custom_per_received = 5
    else:
        custom_per_received = total_received/total_ordered*100
else:
    custom_per_received = 0

frappe.db.set_value("Sales Order", sales_order.name, "custom_per_received", custom_per_received)

sales_order = frappe.get_doc("Sales Order", doc.parent)


items_status = [el.custom_statut_interne for el in sales_order.items]
total_ordered = sum([ 1 if el != "" else 0 for el in items_status])
if total_ordered > 0:
    total_received = sum([ 1 if el == "🟢" else 0 for el in items_status])
    total_started = sum([ 1 if el == "🟠" or el == "⚫️" else 0 for el in items_status])
    if total_received == 0 and total_started > 0:
        custom_per_received = 5
    else:
        custom_per_received = total_received/total_ordered*100
else:
    custom_per_received = 0

frappe.db.set_value("Sales Order", sales_order.name, "custom_per_received", custom_per_received)

# 1. On vérifie que la dépense est bien liée à une transaction bancaire
if not doc.custom_bank_transaction:
    frappe.throw("Veuillez lier cette dépense avec la transaction bancaire correspondante avant de la valider")

# On vérifie que la transaction bancaire n'est pas déjà rapprochée
if frappe.db.get_value("Bank Transaction", doc.custom_bank_transaction, "status") == "Reconciled":
    frappe.throw("La transaction bancaire est déjà réconciliée")

if not doc.cost_center:
    frappe.throw("Le centre de coût est obligatoire")

if not doc.custom_attestation_sur_lhonneur_de_note_de_frais and not doc.receipt:
    frappe.throw("Il manque un justificatif ou une atestation sur l'honneur")

if doc.net_amount == 0:
    frappe.throw("Le total net ne peut pas être de 0")


employee = frappe.get_doc("Employee", doc.employee)
validator_employee = frappe.get_doc("Employee", {
    "user_id": frappe.session.user
})
superiors = employee.get_ancestors()

if superiors and validator_employee.name not in superiors:
    frappe.throw(f"Vous n'êtes pas approbateur. Liste des approbateurs: {', '.join(superiors)}")

employee = frappe.get_doc("Employee", doc.employee)
validator_employee = frappe.get_doc("Employee", {
    "user_id": frappe.session.user
})
superiors = employee.get_ancestors()

if validator_employee.name not in superiors:
    frappe.throw(f"Vous n'êtes pas approbateur. Liste des approbateurs: {', '.join(superiors)}")

for row in doc.time_logs:
    if row.activity_type == "Chantier" and not row.project:
        frappe.throw(
            f"Ligne {row.idx} : Un projet est obligatoire pour le type d'activité 'Chantier'"
        )

user = frappe.form_dict.user
desired_cost_center = frappe.form_dict.cost_center
current_restriction = frappe.db.get_value("User Permission", {"user": user, "allow": "Cost Center"}, ["name", "for_value"])
if current_restriction is None and desired_cost_center:
    doc = frappe.get_doc({
        "doctype": "User Permission",
        "user": user,
        "allow": "Cost Center",
        "for_value": desired_cost_center,
        "apply_to_all_doctypes": 1,
    })
    doc.save()
if current_restriction is not None and not desired_cost_center:
    frappe.delete_doc("User Permission", current_restriction[0])
if current_restriction is not None and desired_cost_center != "":
    frappe.db.set_value("User Permission", current_restriction[0], "for_value", desired_cost_center)

if doc.custom_internal_status == "En compte":
    doc.vt_client_compte = 1
else:
    doc.vt_client_compte = 0
if doc.custom_internal_status == "En compte" and ("*" not in doc.customer_name):
    frappe.msgprint("⚠️ Un client en compte doit avoir une étoile dans son nom", title="Validation")
if doc.custom_internal_status != "En compte" and ("*" in doc.customer_name):
    frappe.msgprint(f"⚠️ Un client {doc.custom_internal_status} ne peut pas avoir une étoile dans son nom", title="Validation")

# On parcourt chaque ligne de la facture
for item in doc.items:
    # Vérifie qu'une référence au Delivery Note existe
    if item.delivery_note:
        # Mise à jour du champ custom_livre à 1 (True)
        frappe.db.set_value("Delivery Note", item.delivery_note, "custom_livré", 1)

doc.weigth_of_visible_items = round(sum([i.total_weight if i.row_print_style != "Hide Row" and i.row_type == "" else 0 for i in doc.items]),1)
doc.qty_of_visible_items = sum([i.qty if i.row_print_style != "Hide Row" and i.row_type == ""  else 0 for i in doc.items])

if doc.company == "Vitrerie Stéphanoise":
    doc.horraire = frappe.db.get_value("Company", doc.company, "custom_opening_hours")
for item in doc.items:
    if item.bom_no:
        item.reference_ligne = frappe.db.get_value("BOM", item.bom_no, "reference_ligne")

err_message = ""
for item in doc.items:
    if not item.project:
        item.project = doc.project
    if not item.cost_center:
        item.cost_center = doc.cost_center
    cond = frappe.db.get_value("Item", item.item_code, "custom_conditionnement_à_lachat")
    if cond:
        err_message = err_message + f"- L'article {item.item_code} est conditionné à l'achat par <b>{cond}</b><br/>"
if err_message:
    frappe.msgprint(
        msg=err_message,
        title='Attention',
    )
doc.custom_label_reference = (frappe.db.get_value("Project Type", doc.custom_type_de_projet, "custom_id") or "") + doc.name.split("ACH")[1].replace("-", "") + (doc.reference_piece or "").upper().replace(" ", "")

for item in doc.items:
    if item.sales_order_item:
        frappe.db.set_value('Sales Order Item', item.sales_order_item, "custom_statut_interne", "🟠")

sales_orders_to_update = list(dict.fromkeys([item.sales_order or "" for item in doc.items]))
for so in sales_orders_to_update:
    if so:
        run_script("Mise à jour des statuts de fabrication dans la commande", doc=frappe.get_doc("Sales Order", so))

naming_series_for_company = {
    "Vision d'O": 'FV/VO-.FY.',
    "Vitrerie Stéphanoise": 'FV/VS-.FY.',
    "Miroiterie Avignonnaise": 'FV/MAV-.FY.',
    "Serrurerie Ferronnerie Métallerie du Luberon": 'FV/SFML-.FY.',
    "EDC SARL": 'FV/EDC-.FY.',
}
doc.naming_series = naming_series_for_company[doc.company]
if doc.custom_type_de_projet is not None and not doc.is_down_payment_invoice:
    t = frappe.db.get_value("Accounting project type", {
        "parent": doc.custom_type_de_projet,
        "company": doc.company,
    }, ["default_product_account"])

    if t is not None:
        if t != "":
            doc.custom_compte_de_produit = t


if doc.custom_compte_de_produit is not None and doc.custom_compte_de_produit != "" and not doc.is_down_payment_invoice:
    for item in doc.items:
        item.income_account = doc.custom_compte_de_produit

if doc.custom_insurance:
    doc.custom_follow_up_automatically = 0

num_of_hours = 0
for i in doc.items:
    if frappe.db.get_value("Item", i.item_code, "custom_pose_vt"):
        num_of_hours = num_of_hours + i.qty*frappe.db.get_value("Item", i.item_code, "custom_number_of_labor_hours")
for i in doc.packed_items:
    if frappe.db.get_value("Item", i.item_code, "custom_pose_vt"):
        num_of_hours = num_of_hours + i.qty*frappe.db.get_value("Item", i.item_code, "custom_number_of_labor_hours")
doc.custom_labour_hours = num_of_hours

fbs = frappe.db.get_list("Fabrication VT", filters={
        "creation": ["between", [doc.starts_on, doc.ends_on]]
    },
    fields=["name", "largeur", "longueur", "quantity", "article"])
qty_article = {}
for f in fbs:
    if f.article not in qty_article:
        price = frappe.db.get_value("Item Price", {
            "item_code": f.article,
            "price_list": "Achat Standard",
            "supplier": "INTERNE"
        }, "price_list_rate") or 0
        qty_article[f.article] = {
            "surface": 0,
            "qty": 0,
            "price": price
        }
    qty_article[f.article]["surface"] = qty_article[f.article]["surface"] + int(f.largeur)/1000*int(f.longueur)/1000
    qty_article[f.article]["qty"] = qty_article[f.article]["qty"] + int(f.quantity)

qty_article = dict(sorted(qty_article.items(), key=lambda item: item[1]["surface"], reverse = True))

doc.total_quantity = sum([i["qty"] for i in qty_article.values()])
doc.total_surface = sum([i["surface"] for i in qty_article.values()])
doc.items = []
doc.raw_material_total_price = 0
for key, value in qty_article.items():
    doc.append('items', {
        "item": key,
        "qty": value["qty"],
        "surface": value["surface"],
        "price_per_m2": value["price"],
        "total_price": value["price"]*value["surface"]*(1+int(doc.loss_percentage)/100)
    })
    doc.raw_material_total_price = doc.raw_material_total_price + value["price"]*value["surface"]*1.2

if doc.overhead_costs > 0:
    doc.per_glass = doc.overhead_costs/doc.total_quantity
    doc.per_surface = doc.overhead_costs/doc.total_surface

doc.price_per_unit = (doc.overhead_costs + doc.raw_material_total_price)/doc.total_quantity
doc.price_per_surface = (doc.overhead_costs + doc.raw_material_total_price)/doc.total_surface

fbs = frappe.db.get_list("Fabrication VT", filters={
        "creation": ["between", [doc.starts_on, doc.ends_on]]
    },
    fields=["name", "quantity", "largeur", "longueur", "article"])
for f in fbs:
    price_per_surface = (frappe.db.get_value("Item Price", {
            "item_code": f.article,
            "price_list": "Achat Standard",
            "supplier": "INTERNE"
        }, "price_list_rate") or 0)*(1+doc.loss_percentage/100)
    frappe.db.set_value("Fabrication VT", f.name, "manufacturing_costs", round(doc.per_glass*int(f.quantity) + price_per_surface*int(f.largeur)/1000*int(f.longueur)/1000,1), update_modified=False)

if frappe.form_dict.get("project"):
    frappe.response['message'] = {
        "project": frappe.form_dict.get("project")
    }
else:
    project = frappe.get_doc({
        "doctype": "Project",
        "customer": frappe.form_dict.get("customer"),
        "project_name": frappe.form_dict.get("quotation_name").split("/")[-1],
        "company": frappe.form_dict.get("company"),
        "address": frappe.form_dict.get("address")
    })

    project.insert()
    if frappe.form_dict.get("quotation_name"):
        frappe.db.set_value("Quotation", 
            frappe.form_dict.get("quotation_name"), 
            "project", project.name, 
            update_modified = False)
    elif frappe.form_dict.get("sales_order_name"):
        frappe.db.set_value("Sales Order", 
            frappe.form_dict.get("sales_order_name"), 
            "project", project.name, 
            update_modified = False)
        # update corresponding quotations
        quotations = list(dict.fromkeys([item.prevdoc_docname for item in doc.items]))
        for q in quotations:
            frappe.db.set_value("Quotation", q, "project", doc.project, update_modified = False)

    frappe.response['message'] = {
        "project": project.name
    }

for item in doc.items:
    if item.against_sales_order:
        doc.delivery_date = frappe.db.get_value("Sales Order", item.against_sales_order, "delivery_date")
        break

doc.custom_follow_up_automatically = doc.custom_type_de_projet == "Enlèvement"
if doc.custom_type_de_projet=="Dépannage" or doc.custom_type_de_projet =="Chantier courant" or doc.custom_type_de_projet == "Chantier stratégique":
    doc.custom_livré = True

if doc.custom_bank_transaction:
    doc.expense_date = frappe.db.get_value('Bank Transaction', doc.custom_bank_transaction, "date")
    doc.grand_total = frappe.db.get_value('Bank Transaction', doc.custom_bank_transaction, "debit")
    if not doc.receipt and not doc.custom_attestation_sur_lhonneur_de_note_de_frais:
        doc.custom_état = "À justifier"
    else:
        doc.custom_état = "Rapprochée et justifiée"
else:
    if doc.receipt:
        doc.custom_état = "À rapprocher"
        corresponding_expense = frappe.db.get_value('Expense', {
            'custom_état': 'À justifier',
            'status': 'Draft',
            'employee': doc.employee,
            'grand_total': doc.grand_total,
        }, ['name', 'custom_bank_transaction'], as_dict=1)
        if corresponding_expense and corresponding_expense.custom_bank_transaction:
            doc.custom_bank_transaction = corresponding_expense.custom_bank_transaction
            doc.custom_état = "Rapprochée et justifiée"
            frappe.delete_doc("Expense", corresponding_expense.name)
            frappe.msgprint(
                msg='Une transaction bancaire correspondante a été trouvé',
                title='Succès',
            )
        else:
            frappe.msgprint(
                msg='Aucune transaction bancaire ne correspond à votre dépense, cela peut prendre plusieurs heures',
                title='En attente de la transaction',
            )
    else:
        doc.custom_état = "À justifier et à rapprocher"

cts = doc.values.splitlines()
for c in cts:
    try:
        d = frappe.get_doc("Carte de travail VT", c)
    except:
        frappe.throw(f"Carte de travail introuvable {c}")
    d.date_de_fin = frappe.utils.getdate()
    d.save()

if doc.address_title:
    doc.name = doc.address_title
else:
    doc.name = doc.address_line1 + frappe.utils.random_string(6)

doc.flags.name_set = True

color = None
if doc.custom_vehicle:
    color = frappe.db.get_value("Vehicle", doc.custom_vehicle, "custom_couleur")
elif doc.custom_employé:
    color = frappe.db.get_value("Employee", doc.custom_employé, "custom_couleur")
else:
    color = "#FFEE00"
doc.color = color

if doc.custom_visite_technique:
    vt = frappe.db.get_value(
    	"Visite Technique", doc.custom_visite_technique, ["starts_on", "ends_on"]
    )
    if vt[0] != doc.starts_on:
    	frappe.db.set_value("Visite Technique", doc.custom_visite_technique, "starts_on", doc.starts_on)

    if vt[1] != doc.ends_on:
    	frappe.db.set_value("Visite Technique", doc.custom_visite_technique, "ends_on", doc.ends_on)

try:
    paiement_request = frappe.get_doc({
        'doctype': 'Payment Request',
        "reference_doctype": "Purchase Invoice",
        "reference_name": doc.name,
        "grand_total": doc.outstanding_amount,
        "bank_account": "BPMED VISION D'O - Banque Populaire",
        "transaction_date": frappe.utils.now()
    })
    paiement_request.insert()
except Exception as e:
    # Ne pas bloquer, même si il y a une erreur dans ce script
    frappe.log_error(e)

time_per_ft = {}
for tl in doc.time_logs:
    if tl.custom_fiche_de_travail:
        time_per_ft[tl.custom_fiche_de_travail] = 0
        if tl.custom_fiche_de_travail not in time_per_ft:
            time_per_ft[tl.custom_fiche_de_travail] = 0
        time_per_ft[tl.custom_fiche_de_travail] = time_per_ft[tl.custom_fiche_de_travail] + tl.hours

for k in time_per_ft:
    time_spent = max(0, frappe.db.get_value("Fiche de travail", k, "time_spent"))
    labor_costs = max(0, frappe.db.get_value("Fiche de travail", k, "labor_costs"))
    percentage_of_time = time_per_ft[k]/doc.total_hours
    frappe.db.set_value("Fiche de travail", k, "labor_costs", round(labor_costs - percentage_of_time*doc.total_costing_amount, 2))
    frappe.db.set_value("Fiche de travail", k, "time_spent", round(time_spent-time_per_ft[k], 2))

doc.custom_day_finished = True
time_per_ft = {}
for tl in doc.time_logs:
    if tl.custom_fiche_de_travail:
        time_per_ft[tl.custom_fiche_de_travail] = 0
        if tl.custom_fiche_de_travail not in time_per_ft:
            time_per_ft[tl.custom_fiche_de_travail] = 0
        time_per_ft[tl.custom_fiche_de_travail] = time_per_ft[tl.custom_fiche_de_travail] + tl.hours

for k in time_per_ft:
    time_spent = max(0, frappe.db.get_value("Fiche de travail", k, "time_spent"))
    labor_costs = max(0, frappe.db.get_value("Fiche de travail", k, "labor_costs"))

    percentage_of_time = time_per_ft[k]/doc.total_hours
    frappe.db.set_value("Fiche de travail", k, "labor_costs", round(labor_costs + percentage_of_time*doc.total_costing_amount, 2))
    frappe.db.set_value("Fiche de travail", k, "time_spent", round(time_spent+time_per_ft[k], 2))

if doc.sales_order:
    doc.status = "Annulé"
    frappe.db.set_value("Sales Order", doc.sales_order, "custom_statut_fiche_de_travail", "")

if doc.sav:
    if not doc.référence_pièce.startswith('SAV - '):
        doc.référence_pièce = 'SAV - ' + doc.référence_pièce
else:
    if doc.référence_pièce.startswith('SAV - '):
        doc.référence_pièce = doc.référence_pièce.replace('SAV - ', '', 1)


if doc.status == "Fait" and not doc.completion_on:
    doc.completion_on = frappe.utils.today()

statuses = [item.status for item in doc.items]
if "⚫️" in statuses:
    doc.avancement = "⚫️"
if "🔴" in statuses:
    doc.avancement = "🔴"
elif "🟠" in statuses:
    doc.avancement = "🟠"
elif "🟢" in statuses:
    doc.avancement = "🟢"
else: doc.avancement = ""
if doc.sales_order:
    frappe.db.set_value("Sales Order", doc.sales_order, "custom_statut_fiche_de_travail", doc.status)
icons = frappe.get_list("Employee", 
    filters={"name": ["in", [t.employé for t in doc.team]]}, 
    fields=["custom_icon"])

if doc.vehicle:
    vehicule_icon = frappe.db.get_value("Vehicle", doc.vehicle, "custom_icon") or ""
else:
    vehicule_icon = ""
doc.calendar_description = "".join([(i.custom_icon or "") for i in icons]) + vehicule_icon + (doc.référence_pièce or "") + (doc.vehicle or "")

if doc.projet:
    vt = frappe.db.get_value("Visite Technique", {
        "projet": doc.projet
    }, "name")
    if not doc.visite_technique:
        doc.visite_technique = vt


doc.total_net_weight = round(sum([item.weight_per_unit*item.quantité for item in doc.items]),2)
doc.total_qty = sum([item.quantité for item in doc.items])
doc.color = '#2438AF'
if doc.ends_on and doc.starts_on_2:
    if doc.full_day:
        doc.scheduled_time = max(0,len(doc.team))*doc.number_of_hours_per_day*(frappe.utils.time_diff(doc.ends_on, doc.starts_on_2).days + 1)
    else:
        doc.scheduled_time = round(max(0,len(doc.team)*frappe.utils.time_diff(doc.ends_on, doc.starts_on_2).seconds/3600),2)
else: 
    doc.scheduled_time = 0

if doc.sav:
    if not doc.référence_pièce.startswith('SAV - '):
        doc.référence_pièce = 'SAV - ' + doc.référence_pièce
else:
    if doc.référence_pièce.startswith('SAV - '):
        doc.référence_pièce = doc.référence_pièce.replace('SAV - ', '', 1)



if doc.status == "Fait" and not doc.completion_on:
    doc.completion_on = frappe.utils.today()


statuses = [item.status for item in doc.items]
if "🔴" in statuses:
    doc.avancement = "🔴"
elif "🟠" in statuses:
    doc.avancement = "🟠"
elif "🟢" in statuses:
    doc.avancement = "🟢"
else: doc.avancement = ""

if doc.sales_order:
    frappe.db.set_value("Sales Order", doc.sales_order, "custom_statut_fiche_de_travail", doc.status)
doc.total_net_weight = round(sum([item.weight_per_unit*item.quantité for item in doc.items]),2)
doc.total_qty = sum([item.quantité for item in doc.items])

icons = frappe.get_list("Employee", 
    filters={"name": ["in", [t.employé for t in doc.team]]}, 
    fields=["custom_icon"])
if doc.vehicle:
    vehicule_icon = frappe.db.get_value("Vehicle", doc.vehicle, "custom_icon") or ""
else:
    vehicule_icon = ""
doc.calendar_description = "".join([(i.custom_icon or "") for i in icons]) + vehicule_icon + (doc.référence_pièce or "") + (doc.vehicle or "")

if doc.projet:
    vt = frappe.db.get_value("Visite Technique", {
        "projet": doc.projet
    }, "name")
    if not doc.visite_technique:
        doc.visite_technique = vt

doc.color = '#2438AF'
if doc.ends_on and doc.starts_on_2:
    if doc.full_day:
